CREATE TABLE predefined_avatars (id UUID PRIMARY KEY, avatar_key VARCHAR(64) NOT NULL UNIQUE, display_name VARCHAR(100) NOT NULL, asset_key VARCHAR(128) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, sort_order INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE conversation_scenario_definitions (id UUID PRIMARY KEY, scenario_key VARCHAR(64) NOT NULL UNIQUE, display_name VARCHAR(120) NOT NULL, description VARCHAR(500) NOT NULL, assistant_display_name VARCHAR(120) NOT NULL, assistant_avatar_key VARCHAR(64) NOT NULL, behavior_instructions VARCHAR(4000) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, sort_order INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL);


